-- Encuesta de cine argentino 2022 (Taipei, La vida útil, La tierra quema): 103 películas por empates.
-- Las que ya estaban en el catálogo solo suman la lista 'encuesta2022'. Generado por data/gen_encuesta.py.

insert into public.peliculas (tmdb_id, media_type, titulo, titulo_tmdb, titulo_original, anio, direccion,
  sinopsis, poster_path, backdrop_path, vote_average, trailer_youtube, listas)
values
  (58429, 'movie', 'La Ciénaga', 'La ciénaga', 'La Ciénaga', 2001, 'Lucrecia Martel', 'Dos familias -una de clase media urbana y otra de productores rurales en decadencia- se entrecruzan en el sopor provinciano de una Salta caótica e inmutable, donde nada sucede pero todo está a punto de estallar.', '/emQIM4vtDbt25tVzdS16w2Gzjbk.jpg', '/7IpUXbKHWA1Xt4jCwnP3A2YFPC3.jpg', 6.8, 'iHikpCDL2_I', '{encuesta2022}'),
  (163924, 'movie', 'Invasión', 'Invasión', 'Invasión', 1969, 'Hugo Santiago', 'Aquilea es una ciudad asediada por misteriosos invasores que pretenden apoderarse de ella. La indiferencia de sus habitantes les allanará el camino; sólo un pequeño grupo de resistentes, guiados por un anciano trata de impedir la acción de los invasores en una lucha desigual.', '/U4rFsDAJyt0MM9at7Tew3LURTl.jpg', '/87SN6j9EYzydPuABOjyt6fjcuoK.jpg', 7.3, 'SDHV6PJAdSU', '{encuesta2022}'),
  (43428, 'movie', 'Tiempo de revancha', 'Tiempo de revancha', 'Tiempo de revancha', 1981, 'Adolfo Aristarain', 'El ex-sindicalista Pedro Bengoa, previa "limpieza" de su pasado, consigue trabajo en las minas de la empresa Tulsaco, donde se reencuentra con un antiguo compañero quien, pasado algún tiempo, le propone un plan: simular un accidente y hacerse pasar por mudo para cobrar una indemnización. Pero algo inesperado sucede.', '/lJK4GKGKqr6v6RfkXOdqkEKKKwk.jpg', '/rg4XBpSQqMDiA0YQiSTxoWJYsIL.jpg', 7.4, 'C-6ExvULsC0', '{encuesta2022}'),
  (36785, 'movie', 'El dependiente', 'El dependiente', 'El dependiente', 1969, 'Leonardo Favio', 'El dependiente es una película argentina en blanco y negro dirigida por Leonardo Favio sobre su propio guion en colaboración con Roberto Irigoyen y Zuhair Jorge Jury según el cuento homónimo de este último. Fue estrenada el 1 de enero de 1969 y sus principales intérpretes son Walter Vidarte, Graciela Borges, Fernando Iglesias (Tacholas), Nora Cullen, Martín Andrade y José E. Felicetti. La película incluye música de Juan Sebastián Bach, Francisco Canaro y Juan de Dios Filiberto interpretada por Yacko Zeller y orquesta.', '/8lnuHlF8Neer4qv7AHH9E4KY6RP.jpg', '/oaPt1lhWnL6BvaTaE537SsAncQC.jpg', 7.0, '2bPmxyQOuKc', '{encuesta2022}'),
  (47142, 'movie', 'Crónica de un niño solo', 'Crónica de un niño solo', 'Crónica de un niño solo', 1965, 'Leonardo Favio', 'Crónica de un niño solo es una película argentina de 1965, la primera dirigida por Leonardo Favio, interpretada principalmente por niños, con Diego Puente en el papel protagónico. Estrenada el 5 de mayo de 1965. Cóndor de Plata como mejor película de 1966. En una encuesta de críticos, historiadores e investigadores del cine realizada en el 2000 por el Museo Nacional de Cine Argentino, una mayoría (75%) la consideraba como la mejor película de la historia del cine argentino.', '/2y3oOFukWhB4itbyIiqR26NDR91.jpg', '/6HAhik5rRetpcIJvcShZIQAapF.jpg', 6.8, null, '{encuesta2022}'),
  (89681, 'movie', 'La hora de los hornos', 'La hora de los hornos', 'La hora de los hornos', 1968, 'Fernando E. Solanas, Octavio Getino', 'Película argentina documental. Está dividido en tres partes: "Neocolonialismo y violencia", "Acto para la liberación" (dividido a su vez en dos grandes momentos:"Crónica del peronismo (1945-1955)" y "Crónica de la resistencia (1955-1966)") y "Violencia y liberación". Muestra la dependencia económica, social y cultural de la Argentina y ofrece pautas sobre cómo superarla.', '/obQJYGM3FTet2CKh1kM4mPs5XAi.jpg', '/dsfRpw40D5XBDaVEZlojGkxyd6S.jpg', 6.9, null, '{encuesta2022}'),
  (427387, 'movie', 'Juan, como si nada hubiera sucedido', 'Juan: Como si nada hubiera sucedido', 'Juan: Como si nada hubiera sucedido', 1987, 'Carlos Echeverría', 'Documental sobre la detención-desaparición de Juan Marcos Herman en la ciudad de Bariloche durante la dictadura en Argentina.', '/320Qy2JxiTVZizBP1ICcLYfOB46.jpg', '/2zAAu1v67CcCU7ea1HtXuUhy4D2.jpg', 8.8, null, '{encuesta2022}'),
  (127471, 'movie', 'Pizza, birra, faso', 'Pizza, birra, faso', 'Pizza, birra, faso', 1998, 'Bruno Stagnaro, Adrián Caetano', 'Cuatro amigos. Una ciudad. Una única salida... El Cordobés vive con sus tres amigos y su mujer embarazada, Sandra, en la misma casa. Los cuatro forman una banda de adolescentes marginales, que pulula por las calles de Buenos Aires, y vive del robo, pero no actúan por cuenta propia, siempre cumplen órdenes de alguien que les quita la mayor parte del botín. La filosofía de vida del Cordobés y los suyos consiste en que mientras no les falte cerveza, pizza y cigarrillos, todo es soportable.', '/gJEpEp0oE7osryIExZgCtyiUtJb.jpg', '/iiSC8rVjkHJw0UmpEMq70xPVQ8H.jpg', 7.0, null, '{encuesta2022}'),
  (49984, 'movie', 'Silvia Prieto', 'Silvia Prieto', 'Silvia Prieto', 1999, 'Martín Rejtman', 'Tras cumplir 27 años, Silvia Prieto decide tomar las riendas de su vida y hacer algunos cambios. Al mismo tiempo, de repente se ve entrelazada en la vida de otra mujer que también se llama Silvia Prieto.', '/r19igTKKB5UFgysxUWsRmXaHVv.jpg', '/4NoosADizDFdr3KLOQ6C5cgSaNr.jpg', 7.1, null, '{encuesta2022}'),
  (18079, 'movie', 'Nueve reinas', 'Nueve reinas', 'Nueve reinas', 2000, 'Fabián Bielinsky', 'Buenos Aires. Juan y Marcos son dos estafadores que están a punto de dar el golpe de sus vidas, el que puede convertirles, al fin, en millonarios. Sólo disponen de 24 horas, pero si lo planifican todo al detalle, nada puede salir mal... o eso creen.', '/v8l85vxFe9J1uEvK9qyIMBlYJNv.jpg', '/e4tZvefBtA6P1T0vAPfeXG4Bj3r.jpg', 7.8, 'O2D3rXfNjWw', '{encuesta2022}'),
  (127467, 'movie', 'Juan Moreira', 'Juan Moreira', 'Juan Moreira', 1973, 'Leonardo Favio', 'Juan Moreira es encarcelado por reclamar lo que le correspondía. Al ser liberado toma justicia por mano propia y signa definitivamente su destino: persecuciones y muertes. Se suma a las huestes de Alsina y entra en la política de Comité. Traicionado se pasa al bando del Gral. Mitre. En medio de estas luchas políticas, del fraude y de las traiciones, librado a su suerte, sólo le quedará una única opción', '/s0B0damR2mmyOPFOvM2JCKZjy0b.jpg', '/u9UbjeHLd3mivXNFqWInsxnR05u.jpg', 7.2, null, '{encuesta2022}'),
  (13653, 'movie', 'El aura', 'El aura', 'El aura', 2005, 'Fabián Bielinsky', 'Un introvertido taxidermista tiene una extraña afición: planificar en su mente atracos perfectos, infalibles gracias a su inteligencia, que él considera superior. El azar hace que un día por fin tenga la oportunidad de llevar a cabo su fantasía, aunque el hecho de sufrir de epilepsia vaya a jugar en su contra.', '/1mHxd9DQLVTLJzWQObgsuewn2kx.jpg', '/fvl1geY63c1xoa6r6iRPARGJdJY.jpg', 7.0, 'zE-PhxHi618', '{encuesta2022}'),
  (226216, 'movie', 'Los traidores', 'Los Traidores', 'Los Traidores', 1973, 'Raymundo Gleyzer', 'Película originalmente destinada para la clase obrera revolucionaria e intelectuales de izquierda. Trata sobre la vida de un militante sindical, que comienza su lucha en las filas peronistas durante los ''60 y se corrompe en su ascenso al poder. La película fue y es considerada por muchos como el único film argentino que profundizó, indagó e investigó con audacia y valentía el accionar histórico de la CGT, su política corrupta y mafiosa. La película propone que la estructura sindical que permitió actuar a esos dirigentes sigue intacta. Los "traidores" de ayer son los mismos que hoy.', '/8rtTsK5p1BFV1jIJx1d1ixwHFp0.jpg', '/wesIJUqspACwHpHZaTs30CKo63M.jpg', 7.6, null, '{encuesta2022}'),
  (214487, 'movie', 'Este es el romance del Aniceto y la Francisca, de cómo quedó trunco, comenzó la tristeza y unas pocas cosas más...', 'Este es el romance del Aniceto y la Francisca, de cómo quedó trunco, comenzó la tristeza y unas pocas cosas más…', 'Este es el romance del Aniceto y la Francisca, de cómo quedó trunco, comenzó la tristeza y unas pocas cosas más…', 1967, 'Leonardo Favio', 'Es la historia de una seducción y enamoramiento entre dos personas de pueblo, en la provincia de Mendoza: Aniceto (Federico Luppi) y Francisca (Elsa Daniel), una chica decente y dulce, "la santita" del Aniceto. Pero el Aniceto también seduce a Lucía (María Vaner), apasionada y sexual, "la putita" del Aniceto. Cuando el romance se rompe, el Aniceto comienza a darse cuenta de lo que perdió.', '/kbch7Aq4M4F777mGcsO7dQ1RamM.jpg', '/liFztEdzFso4e8Ca2uj77rZSZgj.jpg', 6.3, null, '{encuesta2022}'),
  (318591, 'movie', 'Las aguas bajan turbias', 'Las aguas bajan turbias', 'Las aguas bajan turbias', 1952, 'Hugo del Carril', null, '/sktRpfW4ga69nmnW637ApAwncfL.jpg', '/8PwHorTc9fNKDSfi9sEXWqbjvnf.jpg', 7.6, null, '{encuesta2022}'),
  (111188, 'movie', 'Historias extraordinarias', 'Historias extraordinarias', 'Historias extraordinarias', 2008, 'Mariano Llinás', 'X llega a un pequeño pueblo y es testigo de un acto violento; Z toma el trabajo de un gerente muerto y descubre que tenía un cuaderno escrito en código y un mapa; H es contratado para bajar por un río e investigar una serie de misteriosos monolitos construidos en la orilla.', '/SwsmyVX0LAHIGP1YCHPxdJzwBu.jpg', '/a2Equ3sr2n3uE3IUe5y7u1wswsf.jpg', 7.7, null, '{encuesta2022}'),
  (13651, 'movie', 'Esperando la carroza', 'Esperando la carroza', 'Esperando la carroza', 1985, 'Alejandro Doria', 'Mamá Cora, muy cerca ya de los ochenta años, tiene tres hijos y una hija. Vive con uno de ellos, que pasa serios apuros económicos. La familia se reúne un día para celebrar una comida de aniversario, y es entonces cuando se plantea el problema: ¿quién se hará cargo de ella llevándosela a casa?', '/qkSThbNiC6kimvLlWrgeTNYLCeq.jpg', '/3c9csN2cguE6KwIEcJJ06pQVl5s.jpg', 8.1, null, '{encuesta2022}'),
  (127424, 'movie', 'Nazareno Cruz y el lobo', 'Nazareno Cruz y el lobo', 'Nazareno Cruz y el lobo', 1975, 'Leonardo Favio', 'El Poderoso ofrece a Nazareno Cruz toda la riqueza del mundo si accede a abandonar a su amada; de lo contrario, se cumplirá la maldición que supuestamente pesa sobre él.', '/gsWVxyNJuPxhlxmxzIiJahUDJB6.jpg', '/qmptpOgSFZDFBCFtMHBD10Skuhv.jpg', 7.1, null, '{encuesta2022}'),
  (335486, 'movie', 'Más allá del olvido', 'Más allá del olvido', 'Más allá del olvido', 1956, 'Hugo del Carril', 'Después de un periodo de luto, Fernando de Arellano, un rico empresario que acaba de perder a su joven esposa Blanca debido a una grave enfermedad, conoce a Mónica, que es idéntica a ella.', '/fqwHSWYhiPaaD1RBOj9XNmLuV3i.jpg', '/dV65njzYHMCzKSTe8v1P8GqgFfK.jpg', 7.9, 'LLKp2IzCx2c', '{encuesta2022}'),
  (326382, 'movie', 'Zama', 'Zama', 'Zama', 2017, 'Lucrecia Martel', 'Narra la historia de Don Diego de Zama, un oficial español del siglo XVII asentado en Asunción que espera su transferencia a Buenos Aires. Es un hombre que espera ser reconocido por sus méritos. Pero en los años de espera pierde todo. Decide atrapar un peligroso bandido y recuperar su nombre... Basada en la novela existencial de Antonio Di Benedetto escrita en 1956.', '/3pfgZyIJ1AyXD4JB6b0d2IHzTLV.jpg', '/9JqIR7bBO0uofsJiONgYAX2yw1R.jpg', 6.5, 'Txrlcy2893Q', '{encuesta2022}'),
  (335367, 'movie', 'Prisioneros de la tierra', 'Prisioneros de la tierra', 'Prisioneros de la tierra', 1939, 'Mario Soffici', 'Argentina, 1915. Acompañado por un médico y su bella hija, Köhner, un despiadado capataz que gobierna con mano de hierro una plantación de yerba mate, llega a la ciudad de Posadas con el propósito de contratar trabajadores.', '/mriMNgmaWIGcjOlHY7a6G7D02xp.jpg', '/sHHGFQBIBBfp4lItfg5j6YMpJuM.jpg', 6.4, null, '{encuesta2022}'),
  (37061, 'movie', 'Gatica, el mono', 'Gatica el Mono', 'Gatica el Mono', 1993, 'Leonardo Favio', 'José María Gatica "el Mono" fue uno de los boxeadores argentinos más populares de los años cuarenta. Pese a su gran talento, él no supo aprovecharlo y fue autodestuyéndose, despilfarrando el dinero y dejando de lado los entrenamientos por las juergas nocturnas, perdiendo así la oportunidad de una gran carrera internacional. Este film retrata la vida de uno de los personajes más controvertidos de la historia argentina, desde su infancia en Buenos Aires hasta su éxito veinte años más tarde, y finalmente su dramático fracaso condicionado por los cambios políticos después de la muerte de Perón.', '/lcgIbWjfmQYWPNyJxy9WdSmE2Zp.jpg', '/iXjkTgICu8ZdKZtxWQdamicP1oL.jpg', 7.3, null, '{encuesta2022}'),
  (128489, 'movie', 'Rosaura a las diez', 'Rosaura a las 10', 'Rosaura a las 10', 1958, 'Mario Soffici', 'Todo comenzó con un crimen. O mejor, todo comenzó unos seis meses antes, "aquella mañana en el que el cartero trajo un sobre rosa con un detestable perfume a violetas". Los sobres van llegando puntualmente, cada miércoles, a la pensión La Madrileña. El olor a violetas invade las habitaciones de los inquilinos, que se convertirían en testigos del encuentro entre Rosaura y Camilo Canegato, el tímido restaurador de cuadros. Sin embargo, cuando Rosaura es encontrada muerta, cada uno de los personajes tendrá que dar su versión de la historia.', '/3lIPt9LW9gTcSiHQtukc71vl8Jg.jpg', '/fBjiScpRrNfwxbEUHprtTlhMCcx.jpg', 7.4, null, '{encuesta2022}'),
  (269054, 'movie', 'Pajarito Gómez (una vida feliz)', 'Pajarito Gómez, una vida feliz', 'Pajarito Gómez, una vida feliz', 1965, 'Rodolfo Kuhn', '"Pajarito" Gómez es un cantante de música popular impulsado por una empresa discográfica. La historia se centra en la vida de Pajarito fuera de los escenarios, cómo se construye su figura pública alimentando el mito del muchacho pobre, provinciano, que por su talento -y siendo al mismo tiempo buen hijo y buen ciudadano- alcanza la fama y la fortuna. Detrás de esta fachada, Pajarito es un hombre oscuro y desorientado, alcohólico, distanciado de su madre.  Se trata de una exposición cruda y satírica de los medios de comunicación y su modo de representar (recortar, tergiversar o, llanamente, inventar) la realidad.', '/zfQESzAA7LzdnbzfAnekc7FdIoK.jpg', '/pORMgQgGqVUWrQMxGkjV2aQBlYJ.jpg', 7.1, null, '{encuesta2022}'),
  (193302, 'movie', 'Los rubios', 'Los rubios', 'Los rubios', 2003, 'Albertina Carri', '''Los rubios'' es un recorrido por diversos estados de la memoria a partir de la ausencia de los padres de la protagonista. Fragmentos, fantasías, relatos y fotos dan forma a una realidad que pertenece al pasado y se proyecta en el presente. Un equipo de filmación a la deriva, una actriz y unos Playmobiles felices construyen el universo fracturado en que la protagonista descubre una y otra vez lo imposible de la memoria.', '/vRrjM2ieeV91H3V3oX9EZ6eyBwE.jpg', '/nxT9oKwx8frC6MDIbGEFFF8TISn.jpg', 6.0, null, '{encuesta2022}'),
  (199194, 'movie', 'La casa del ángel', 'La casa del ángel', 'La casa del ángel', 1957, 'Leopoldo Torre Nilsson', 'Ana es una adolescente que ha crecido en un ambiente represivo e hipócrita. El descubrimiento del sexo y de la crudeza de la vida significan el fin de su inocencia.', '/hiXViC8aU1WUobup3Cq8cv6KRt3.jpg', '/uRmYElghJ9SnsmTJkQvQmfHZ3s4.jpg', 7.2, null, '{encuesta2022}'),
  (42085, 'movie', 'Camila', 'Camila', 'Camila', 1984, 'María Luisa Bemberg', 'Un filme basado en hechos reales que narra la historia de amor que mantuvieron, en el siglo XIX, la aristócrata Camila O''Gorman y el sacerdote Ladislao Gutiérrez. Una relación que provocó el escándalo entre la iglesia y la sociedad de la época.', '/ibSmdjvNXWQgZKLPeJNReRLTJrF.jpg', '/1BH1XATWO5NmJezvaGnvkfe6mq2.jpg', 7.2, '6Uv4WNFtupE', '{encuesta2022}'),
  (151441, 'movie', 'Tire dié', 'Tire dié', 'Tire dié', 1958, 'Fernando Birri', 'Todos los días los niños del barrio conocido como "Tire Dié", en la ciudad de Santa Fe, esperan el tren para pedir dinero, al grito de "¡Tire Dié!" (¡tírame un centavo!) a los pasajeros. Considerada la primera encuesta sobre cine en América Latina.', '/f1SQDSG2faqhjX4pMjnuxTG80FX.jpg', '/iO4HKGPngeYqsuk1wX32tOBGFBR.jpg', 7.1, 'GzF8HaLBDOA', '{encuesta2022}'),
  (8898, 'movie', 'La mujer sin cabeza', 'La mujer rubia', 'La mujer sin cabeza', 2008, 'Lucrecia Martel', 'Una mujer, en una distracción mientras conduce, atropella algo. Al cabo de unos días le cuenta a su marido que ha matado a alguien en la carretera. Recorren la ruta pero sólo hay un perro muerto, y amigos allegados a la policía confirman que no hay información de un accidente. Todo vuelve a la calma y el mal momento parece superado, hasta que la noticia de un macabro hallazgo preocupa nuevamente a todos.', '/a7sFZUcMzCbG8CbvmsTsgWt37Si.jpg', '/aXE1bX9jl3YLq9D5WuNYBNTERZN.jpg', 6.2, 'hGiO1c-woNo', '{encuesta2022}'),
  (127423, 'movie', 'Soñar, soñar', 'Soñar, soñar', 'Soñar, soñar', 1976, 'Leonardo Favio', 'Un joven trotamundos conoce a un empleado que sueña con ser artista y juntos intentarán la aventura de ser famosos.', '/vc30zARSmbcnmS5BifqPWEMuKF9.jpg', '/tcB5wbuH5fQcHnvoCVta3R1KHs1.jpg', 7.0, null, '{encuesta2022}'),
  (64978, 'movie', 'La Patagonia rebelde', 'La Patagonia rebelde', 'La Patagonia rebelde', 1974, 'Héctor Olivera', 'En 1920, los trabajadores de la Patagonia, en el sur de Argentina, se reúnen en torno a una sociedad anarcosindicalista y hacen huelga, exigiendo mejores condiciones de trabajo. Cuando la situación se vuelve insostenible, el presidente Yrigoyen envía al teniente coronel Zavala para imponer el orden.', '/oj6OeVMhquRV64gIjxbyoHgaSCL.jpg', '/zrAsAn9S6EPmWfBS7INcSoS7TlH.jpg', 7.6, 'g3s9alUwSos', '{encuesta2022}'),
  (288151, 'movie', 'El acto en cuestión', 'El acto en cuestión', 'El acto en cuestión', 1994, 'Alejandro Agresti', null, '/uweda7xneGnOeXH5nzY3M95SFXz.jpg', '/3M4kaEnUIKODMvCKPWuE5L9WENO.jpg', 7.3, null, '{encuesta2022}'),
  (127449, 'movie', 'La tregua', 'La tregua', 'La tregua', 1974, 'Sergio Renán', 'Martín Santomé, un viudo con tres hijos, comienza a registrar en un diario íntimo la vida cotidiana y anódina de la oficina y las tensiones de su vida familiar. Un día, a punto de jubilarse, irrumpe en su vida la joven Laura Avellaneda, y Martín descubre que aún está vivo. Superados los temores que les infunde la gran diferencia de edad que hay entre ellos, se atreven a correr el riesgo de vivir una relación amorosa.', '/1R0I3Jm91smJnt84HEJTg61cAKP.jpg', '/oJDuXOSfoQlNW4N9QXz6s8gOFfh.jpg', 7.5, '2BejRic_gT0', '{encuesta2022}'),
  (252696, 'movie', 'Apenas un delincuente', 'Apenas un delincuente', 'Apenas un delincuente', 1949, 'Hugo Fregonese', 'Después de perder su dinero en el juego, José Morán decide estafar a la empresa donde trabaja en una importante suma de dinero, esconder mientras cumple la condena de seis años de cárcel que le dan por el hecho y disfrutarlo a su salida. Una vez en la cárcel la vida se complica tanto para él como para su familia y poco a poco el plan perfecto empieza a develarse como un terrible error.', '/6n6WwQ3cdvG58Gwjyh2LrTTkOoI.jpg', '/dxm98TNCuMxDuKjlUP1I9GvhsrP.jpg', 6.9, null, '{encuesta2022}'),
  (29263, 'movie', 'La historia oficial', 'La historia oficial', 'La historia oficial', 1985, 'Luis Puenzo', 'Buenos Aires, Argentina, 1983. En los últimos y turbulentos días de la dictadura militar, Alicia, profesora de historia en un instituto, comienza a hacer preguntas incómodas sobre los oscuros orígenes de Gaby, su hija adoptiva.', '/aUpMovE1AS9UHm893e3YsFLR2aB.jpg', '/qYQmznfMC433HrX5m58MJB0QOlK.jpg', 7.5, 'jZtJRa5XP28', '{encuesta2022}'),
  (423778, 'movie', 'La flor', 'La flor', 'La flor', 2019, 'Mariano Llinás', 'Un enorme esfuerzo de complejidad narrativa compuesto por seis historias independientes y sucesivas, conectadas por las mismas cuatro actrices que viven experiencias muy diferentes en universos muy distintos.', '/GMAnDHh4m2mn8schv9DtWF6khv.jpg', '/8fylml4dfpIpl5dPP0TGvVGA7eg.jpg', 7.3, 'rPNxAqeixF0', '{encuesta2022}'),
  (115316, 'movie', 'La película del rey', 'La película del rey', 'La película del rey', 1986, 'Carlos Sorín', 'Narra la historia legendaria de un ciudadano francés, Oreille Antoine de Tounens, que en 1860 se autoproclamó rey de la Patagonia y Araucania es tomada por un director que viaja al sur para filmarla. Los entretelones de la filmación, con problemas financieros, técnicos y deserciones dentro del elenco, empiezan a tener paralelismos con el tema de la película. El director queda prácticamente sólo en una geografía que lo lleva al borde de la locura... Opera prima del director Carlos Sorín, premiada en los festivales de Venecia y de La Habana, y ganadora del Premio Goya al mejor film latino.', '/i6Po2W3awctrZ8FQViT3IEj2K3N.jpg', '/p95JNuHpUI1vlm0lDun56iJ5gsu.jpg', 5.3, 'S6g7t-Q5nvk', '{encuesta2022}'),
  (44413, 'movie', 'La niña santa', 'La niña santa', 'La niña santa', 2004, 'Lucrecia Martel', 'Amalia es una niña como las otras del coro, que se cuestionan sus creencias religiosas. Cuando el Dr. Jano llega a dar una charla al hotel donde Amalia vive con su madre, ella siente que tiene una misión: librar del pecado a ese hombre que está seduciendo a su madre.', '/6Wjt2ZIWSNLudz6MByaIknWeval.jpg', '/s1K8dZkKIhhsrdUPE27AWaiK4fQ.jpg', 6.6, 'BY6M-Datddg', '{encuesta2022}'),
  (30909, 'movie', 'Si muero antes de despertar', 'Si muero antes de despertar', 'Si muero antes de despertar', 1952, 'Carlos Hugo Christensen', 'Mientras comete una travesura, un niño descubre accidentalmente la identidad de un criminal que merodea por el barrio.', '/jyPIYq55oXtseUYtjF1uD2rZ38t.jpg', '/w2Wg64ckSZUrRIYc0EHDo50RslK.jpg', 6.6, null, '{encuesta2022}'),
  (265195, 'movie', 'Relatos salvajes', 'Relatos salvajes', 'Relatos salvajes', 2014, 'Damián Szifron', 'La desigualdad, la injusticia y la exigencia del mundo en que vivimos producen que muchas personas se estresen o se depriman. Algunas explotan. Esta es una película sobre ellos. Vulnerables ante una realidad que súbitamente se altera y se torna impredecible, los protagonistas cruzan la delgada frontera que divide a la civilización de la barbarie. Una traición amorosa, el retorno de un pasado reprimido, o la violencia contenida en un detalle cotidiano, se presentan para impulsarlos al vértigo de perder los estribos, al innegable placer de perder el control.', '/vimbRR5XdkMj7CqnzVN92Cla8jN.jpg', '/dHnki2Dh6lbOtfksrh8H5lg08f5.jpg', 7.9, 'Utq0aDEp084', '{encuesta2022}'),
  (49913, 'movie', 'Bolivia', 'Bolivia', 'Bolivia', 2002, 'Adrián Caetano', 'Freddy emigra a Buenos Aires en busca de una vida más próspera. En su país natal, Bolivia, deja a su familia. Sin embargo, la capital argentina no es el paraíso que Freddy soñó, y mucho menos para los emigrantes ilegales como él. Pese a ello, consigue trabajo como cocinero en un restaurante. Un aclamado filme de bajo presupuesto premiado en varios festivales.', '/hBqMklEq66l3bD48wS1izH4My1Y.jpg', '/nvYzkjzoaqm9wzdPPqZLtwK1S4T.jpg', 7.3, null, '{encuesta2022}'),
  (25376, 'movie', 'El secreto de sus ojos', 'El secreto de sus ojos', 'El secreto de sus ojos', 2009, 'Juan José Campanella', 'Argentina. Benjamín Espósito es oficial de un Juzgado de Instrucción de Buenos Aires recién retirado. Obsesionado por un brutal asesinato ocurrido veinticinco años antes, en 1974, decide escribir una novela sobre el caso, del cual fue testigo y protagonista. Reviviendo el pasado, viene también a su memoria el recuerdo de una mujer, a quien ha amado en silencio durante todos esos años.', '/4qGglMWuI4dHMHX8pMr1BbwaXkW.jpg', '/zaANf06OtqDJr5saqp5ymEkDPsi.jpg', 8.0, 'GcHkTSqeGoU', '{encuesta2022}'),
  (204192, 'movie', 'Los inundados', 'Los inundados', 'Los inundados', 1962, 'Fernando Birri', 'Narra la historia de una familia de pocos recursos, habitantes del sur de la provincia de Santa Fe, que se ve forzada a mudarse a un vagón abandonado del ferrocarril hasta que bajen las aguas del río Salado.', '/g36EDAe3HMHPhdwobamXccSA7OD.jpg', '/k4EArGgkJrHh5XrRBG3To9XBckj.jpg', 7.4, null, '{encuesta2022}'),
  (32635, 'movie', 'Un lugar en el mundo', 'Un lugar en el mundo', 'Un lugar en el mundo', 1992, 'Adolfo Aristarain', 'Ernesto hace un viaje a San Luis, un pueblo de un remoto valle de Argentina, para recordar su infancia y las circunstancias que han determinado su vida: sus padres se habían exiliado voluntariamente de Buenos Aires para vivir en una comunidad campesina; la llegada de un geólogo español, contratado por el cacique local para buscar petróleo, representa una amenaza para la forma de vida de los campesinos.', '/6mZ5HWapYvTdA1ABNaSLZFqnoW7.jpg', '/zXKKvPstrabP07BXNAUgXKZGetB.jpg', 7.5, 'DRLNojIUq04', '{encuesta2022}'),
  (518776, 'movie', 'El silencio es un cuerpo que cae', 'El silencio es un cuerpo que cae', 'El silencio es un cuerpo que cae', 2017, 'Agustina Comedi', 'Agustina encontró las cintas de video que su padre Jaime grabó antes del accidente que le quitó la vida. Los secretos familiares que su historia y la de Jaime la empujarán a involucrarse en una búsqueda que revelará una historia marcada la sexualidad y el activismo político.', '/iQrsPKVtqP5OtCuxeUpZ6qtieK7.jpg', '/6DtbbpgM4HUSaNog3XltDziceeQ.jpg', 6.0, '0NxBkrGL2o8', '{encuesta2022}'),
  (268653, 'movie', 'Tiro de gracia', 'Tiro de gracia', 'Tiro de gracia', 1969, 'Ricardo Becher', 'Una joven pareja deambula por la noche de la ciudad de Buenos Aires mostrando sus símbolos, sus personajes y secretos.', '/l6aPyUboIBJlInUnyyJdl7N8UOt.jpg', '/1SwPmPwOQ0upx982rWl5d1hSMM8.jpg', 6.2, null, '{encuesta2022}'),
  (265626, 'movie', 'Últimos días de la víctima', 'Últimos días de la víctima', 'Últimos días de la víctima', 1982, 'Adolfo Aristarain', 'A Mendizábal, un asesino a sueldo, sus anónimos clientes le ordenan un nuevo asesinato. Pero en la persecución, precisa y obsesiva, descubrirá que solo forma parte de un juego que no le pertenece, de una cadena al servicio de intereses mayores.', '/ctRPbhNzihncgtrQpOHAwNLkLGi.jpg', '/6Gb3ILjcAozr6fMiwfyTQRz5r9f.jpg', 7.4, null, '{encuesta2022}'),
  (481173, 'movie', 'La fe del volcán', 'La fe del volcán', 'La fe del volcán', 2002, 'Ana Poliak', 'Es la historia de Ani, una aprendiz de peluquera que pierde su trabajo y Danilo, un afilador de tijeras que pedalea la ciudad en su "despacho rodante".', '/tn37MJU3pU01PoBDWu0ETEraTgr.jpg', '/gqTkxIULe7Bf1PRPZCUZCIJ2x6T.jpg', 5.8, null, '{encuesta2022}'),
  (440132, 'movie', 'Cuatreros', 'Cuatreros', 'Cuatreros', 2016, 'Albertina Carri', 'Albertina Carri quiere hacer una película sobre Isidro Velázquez, un forajido casi mítico del norte de Argentina que fue asesinado a tiros por la policía en 1967. No es la única interesada en él: su padre, el sociólogo Roberto Carri, escribió un libro sobre él llamado “Pre -Formas revolucionarias de violencia” y se hizo una película sobre su historia, aunque tanto el padre como la película desaparecieron durante la Guerra Sucia. Leyendas, familias, alineaciones políticas, cine: ninguna ofrece un punto de apoyo estable y el paso de Carri a través de ellas es como deambular por un jardín de senderos que se bifurcan, solo para llegar a un paisaje de tierra agrietada y espinas.', '/4ZcVaQ2slANbKsrDTN6co57Kwhx.jpg', '/a80wuk6deiqvScnX9eWdrB3kGEu.jpg', null, null, '{encuesta2022}'),
  (125948, 'movie', 'Un oso rojo', 'Un oso rojo', 'Un oso rojo', 2002, 'Adrián Caetano', 'Aunque solo Oso lleva la cuenta, han pasado siete años desde que cayó preso por homicidio y robo a mano armada. Es un hombre parco, impredecible, violento por naturaleza o por necesidad, y es probable que en todos estos años no le haya dicho a nadie lo que oculta en sus silencios y la tristeza de su mirada. Ahora, mientras sale a la calle en libertad condicional, Oso piensa que tal vez pueda volver a empezar. El Turco le debe todavía su parte del asalto, y a través de un compañero de celda contacta con Güemes, que lo emplea como chofer en su agencia de taxis. Oso ha perdido a su mujer, que vive ahora con Sergio, y su hija apenas lo recuerda, pero él está dispuesto a recuperarlas o al menos a reparar los daños. Como un western desencantado y urbano, Un Oso Rojo imagina el destino de un justiciero marginal en la crudeza real de un suburbio porteño.', '/dUbv0BuEHrDDvvoQ14OaBeBrpXu.jpg', '/7jmPLMQyNv746EZED5uMSSFdny9.jpg', 7.1, 'NX4Yx-ZwrPk', '{encuesta2022}'),
  (101338, 'movie', 'Mundo grúa', 'Mundo grúa', 'Mundo grúa', 1999, 'Pablo Trapero', 'Rulo busca trabajo a sus 50 años como operador de grúas de construcción, pero debe pasar por diferentes pruebas para obtener el puesto. Mientras se esfuerza por mantener a su madre y a su hijo Claudio de 19 años que intenta montar su propria banda de rock, Rulo tendrá que resignarse a aceptar un puesto a 2.000 kilómetros de distancia de Buenos Aires, aunque el largo período de adaptación le servirá de poco y tendrá que replantearse volver a empezar de nuevo.', '/uWJccSIj9CHt6ecteD79iN95VqN.jpg', '/hoAUWqdkXffHa13H0ZKBdVPovGx.jpg', 6.1, '3hH5yb8BsnA', '{encuesta2022}'),
  (46770, 'movie', 'Sur', 'Sur', 'Sur', 1988, 'Fernando E. Solanas', 'Sur nos habla del reencuentro y de la amistad. Es el triunfo de la vida sobre la muerte, del amor sobre el rencor, de la libertad sobre la opresión, del deseo sobre el temor. Sur nos cuenta una historia de amor. Es el amor de la pareja y es también una historia de amor por un país. Es la historia de un regreso.  Sur, es un homenaje a todos los que, como el personaje tartamudo, supieron decir NO. Fueron los que mantuvieron la dignidad. Ellos dijeron no a la injusticia, a la opresión, y a la entrega del país a manos de quienes no lo merecen.', '/xyOeNv5YturVNqxBFQ5DQAKjp3E.jpg', '/yUbeQkMsLMXt2zlDJpEW289qZzT.jpg', 6.6, null, '{encuesta2022}'),
  (48797, 'movie', 'Hombre mirando al sudeste', 'Hombre mirando al sudeste', 'Hombre mirando al sudeste', 1987, 'Eliseo Subiela', 'El doctor Julio Denis es un médico psiquiatra y trabaja en un neuropsiquiátrico. Un día llega al hospital un joven, Rantés, que dice ser un ser de otro planeta. Lo trata como paranoico, pero Rantés irá introduciéndose en su vida, haciéndolo dudar de si realmente está loco, con lo que, sutilmente, lo obliga a replantear su vida y profesión.', '/nopMzXaxd2n3NJkhbWbvqf5MIY9.jpg', '/yhquZtwnsCZdXHxiaMuzVqFW8qC.jpg', 7.5, 'nNBquvLlFDI', '{encuesta2022}'),
  (335489, 'movie', 'Breve cielo', 'Breve cielo', 'Breve cielo', 1969, 'David José Kohon', 'Un joven de clase media tiene un romance con una chica muy humilde durante las vacaciones de sus padres.', '/hj2KN52KJcKF5JiDtWceq1Yd4e7.jpg', '/cPBe7JZlVO6mpE7ZAmrS7YiwrCY.jpg', 6.3, null, '{encuesta2022}'),
  (185250, 'movie', 'Los tallos amargos', 'Los tallos amargos', 'Los tallos amargos', 1956, 'Fernando Ayala', 'Buenos Aires, Argentina. Un reportero fracasado se asocia con un inmigrante húngaro para crear una falsa escuela de periodismo por correspondencia.', '/fsUYBlUrns2eODsbdLmlCZ56LFY.jpg', '/g3gTGqKxjaNmOmEUQ9OLyejeL0l.jpg', 7.1, null, '{encuesta2022}'),
  (379044, 'movie', '¡Que vivan los crotos!', '¡Que vivan los crotos!', '¡Que vivan los crotos!', 1995, 'Ana Poliak', 'Un día del año 1930, José Américo Ghezzi (Bepo), picapedrero anarquista sin trabajo, abandona su pueblo y hasta 1955 no regresa. Durante 25 años camina sin otro rumbo que el trazado por las vías del ferrocarril, sumándose al silencioso mundo de los “crotos” en el que se encuentra al “francés”, maestro de vida que lo marcó para siempre. En su pueblo, sus amigos y una mujer lo esperan tejiendo sus propias vidas. 60 años más tarde, frente a una cámara, reviven sus amores y visiones del mundo en una suerte de collage de miradas y sueños donde lo primordial es la pregunta: ¿La libertad es posible?', '/olZRksdGrRDMNpfBkYljVU829hl.jpg', '/1QIZKqdw5wnbxr7W1dS7rk1tzDp.jpg', 6.0, null, '{encuesta2022}'),
  (135575, 'movie', 'Picado fino', 'Picado fino', 'Picado fino', 1998, 'Esteban Sapir', 'Los problemas de un joven, su novia embarazada y su amante.', '/sS9W2OTu7gx5HM0xlT79PZxBuZz.jpg', '/aaaJDjnVtne77ENTKP26VUyrj1L.jpg', 6.4, null, '{encuesta2022}'),
  (252695, 'movie', 'No abras nunca esa puerta', 'No abras nunca esa puerta', 'No abras nunca esa puerta', 1952, 'Carlos Hugo Christensen', 'Un hombre intenta vengar la muerte de su hermana, una adicta al juego. Otro hombre, un expresidiario que silba cuando comete un crimen, se reencuentra con su madre ciega.', '/xc15g5hADvdSFUv7uetW3vQ1JkW.jpg', '/fgmspgqVwPOhebYOyL19CMp0AvM.jpg', 7.2, 'LfJsmNW9BzM', '{encuesta2022}'),
  (51378, 'movie', 'Historias mínimas', 'Historias mínimas', 'Historias mínimas', 2002, 'Carlos Sorín', 'A miles de kilómetros al sur de Buenos Aires, tres personajes viajan por las solitarias rutas de la Patagonia. Don Justo, un anciano de ochenta años, que es el dueño de un bar de carretera que regenta su hijo, se ha escapado de casa para buscar a su perro desaparecido desde hace tiempo. Roberto, un viajante de comercio de cuarenta años, lleva en su viejo coche una tarta de crema para el cumpleaños del hijo de la joven viuda de uno de sus clientes. Ese mismo día María Flores, una joven de 25 años, viaja con su hija en autobús siguiendo la misma ruta. Es una mujer muy humilde que acaba de saber que ha resultado ganadora en un sorteo de un programa de TV, cuyo premio mayor es un robot de cocina. Cada uno viaja por su cuenta, pero como sucede en las desérticas rutas patagónicas, sus vidas y sus ilusiones se entrecruzan en los escasos paradores de la región.', '/dD27iIMNImAnGlSs7OroS0lvV95.jpg', '/w2QUsItk4yAo0UwW86QJxnxgs5F.jpg', 7.3, 'Ylxk1a46GaI', '{encuesta2022}'),
  (78237, 'movie', 'Tiempo de valientes', 'Tiempo de valientes', 'Tiempo de valientes', 2005, 'Damián Szifron', 'Mariano Silverstein es un psicoanalista que a raíz de un accidente de tráfico está involucrado en un juicio penal. Comprometido a realizar tareas comunitarias dentro de su actividad, el juez le asigna a atender a Alfredo Díaz, un inspector de la Policía Federal anímicamente devastado por la infidelidad de su mujer. Así es como Silverstein debe improvisar una itinerante sesión de psicoanálisis mientras acompaña a Díaz en la investigación de un crimen, sumergiéndose progresivamente en el universo policial. Pero eventos fuera de programa dispararán la trama hacia zonas inesperadas, obligando a nuestros héroes a enfrentarse a grandes peligros, físicos y emocionales, para los que, por supuesto, no estarán preparados.', '/ZZ00teEWJMPEAqSYJ6xIxNTu4q.jpg', '/q2ZFyrDHq7vDk0buN4DE9ch6HQ6.jpg', 7.5, 'Nx6TTK7PRiA', '{encuesta2022}'),
  (341589, 'movie', 'Los muchachos de antes no usaban arsénico', 'Los muchachos de antes no usaban arsénico', 'Los muchachos de antes no usaban arsénico', 1976, 'José A. Martínez Suárez', 'Mara Ordaz, una antigua estrella de cine que vive en una mansión aislada con su marido, su médico y el administrador de sus bienes, decide vender la casa y volver a Buenos Aires; pero los tres hombres no están de acuerdo con su decisión.', '/ijvG3LwdTk8VxhTMjPyfmcwqJpj.jpg', '/NoPxQqULMSLCB18Y94ejLsQUMd.jpg', 7.6, null, '{encuesta2022}'),
  (261263, 'movie', 'Los hijos de Fierro', 'Los hijos de Fierro', 'Los hijos de Fierro', 1978, 'Fernando E. Solanas', 'Análisis del período político que va desde la caída de Perón hasta su regreso de España. Se basa en una suerte de paralelismo entre la figura de Martín Fierro y la de Juan Domingo Perón, sin olvidar el destino histórico de sus seguidores.  La película se rodó en los años ''70, y el montaje se llevó a cabo en el exilio. Por fin, pudo ser estrenada en 1984, gracias a la restauración de la democracia.', '/ghd8LhDRHasRK3HqvtZB2MEV9yS.jpg', '/xbG3o2NbwXgS5Dj851bnPwdmfAV.jpg', 6.4, null, '{encuesta2022}'),
  (182469, 'movie', 'Tangos, el exilio de Gardel', 'El exilio de Gardel: Tangos', 'El exilio de Gardel: Tangos', 1985, 'Fernando E. Solanas', 'Unos argentinos, exiliados en París, deciden montar un tango-ballet, dedicado a Carlos Gardel, una legendaria estrella del tango argentino.', '/zQRi8YujjyglVuBiMjDOGjB5xFs.jpg', '/tOH2ZhhVSJsxl66vHZM53ElvUgO.jpg', 6.8, '5jKUFKEaKA4', '{encuesta2022}'),
  (343008, 'movie', 'Ofrenda', 'Ofrenda', 'Ofrenda', 1978, 'Claudio Caldini', 'Cortometraje que muestra margaritas a lo largo del día con música como acompañamiento.', '/ckEMdCKXdfG9j4KB4jabraOqgmh.jpg', '/5NzRrEsDzhpXhlVEFAWcvOMsZwc.jpg', 6.2, null, '{encuesta2022}'),
  (215868, 'movie', 'La parte del león', 'La parte del león', 'La parte del león', 1978, 'Adolfo Aristarain', 'Historia de un hombre común y corriente que, por casualidad, toma posesión del dinero que fue robado de un banco, creyendo que así podrá solucionar todos sus problemas.', '/r4Ih9CUXFIQ01XiOiZhxTmal1h0.jpg', '/5KzPx5gdKCUaomXOWD7tRrxXZoI.jpg', 6.6, null, '{encuesta2022}'),
  (121461, 'movie', 'La mano en la trampa', 'La mano en la trampa', 'La mano en la trampa', 1961, 'Leopoldo Torre Nilsson', 'Terminados sus estudios en un internado, Laura regresa a la sombría casa donde vive con su madre y su tía. Sabe que en el desván vive escondido un ser del que la familia se avergüenza. Con la ayuda de su novio acaba descubriendo quién habita en ese desván y qué secreto le ocultan todos.', '/3VkthMudOFfkTwEAdnFfU8OmEk.jpg', '/cdvTd813WZgGDhQkFUNn35QKyRt.jpg', 6.5, null, '{encuesta2022}'),
  (435404, 'movie', 'Gente en Buenos Aires', 'Gente en Buenos Aires', 'Gente en Buenos Aires', 1974, 'Eva Landeck', 'Dos jóvenes viven un romance telefónico sin saber que se conocen personalmente y se tienen una gran antipatía.', '/nn150fJuJ5OaeX2UsKWLYoe1FaI.jpg', '/oZXro5nAvd8dSjMjJTejw4Atew2.jpg', 6.8, null, '{encuesta2022}'),
  (62499, 'movie', 'Boquitas pintadas', 'Boquitas pintadas', 'Boquitas pintadas', 1974, 'Leopoldo Torre Nilsson', 'Un hombre enfermo de tuberculosis sostiene relaciones amorosas con varias mujeres y las contagia.', '/8a4K3sb9dzsnzWw4pZVFMXhHegP.jpg', '/wLMls45IkzJ7IKO1g0xxEn7NEjW.jpg', 6.6, null, '{encuesta2022}'),
  (385630, 'movie', 'Un muro de silencio', 'Un muro de silencio', 'Un muro de silencio', 1993, 'Lita Stantic', 'Una directora de cine llega a Buenos Aires para filmar sobre una mujer, cuyo esposo desapareció durante la dictadura.', '/4vNIPlU1WsJr1vYgxeIdf3jUjRH.jpg', '/7jzD0CE1z6fGBEORFnqZpYcHsbk.jpg', 5.7, null, '{encuesta2022}'),
  (127022, 'movie', 'Señora de nadie', 'Señora de nadie', 'Señora de nadie', 1982, 'María Luisa Bemberg', 'Es la historia de Leonor, una buena ama de casa que vive con su marido, Fernando, y sus dos hijos. Ama profundamente a su marido y no pone en duda la reciprocidad de su amor y su fidelidad. Un día, circunstancialmente, descubre que su marido la engaña. Leonor se siente traicionada emocionalmente y comprende que su mundo, basado en una mentira, se ha desmoronado como un castillo de naipes. Con más miedo que convicción, abandona la casa, dejando cartelitos con instrucciones precisas para su marcha y confía a sus hijos al cuidado de su marido.', '/A7eSI0h2oRM2Xs4FGNtcGiG4DIn.jpg', '/v1csl8Tm4SZUkqbs76Hr2p5mWkt.jpg', 7.0, null, '{encuesta2022}'),
  (36241, 'movie', 'Los muertos', 'Los muertos', 'Los Muertos', 2004, 'Lisandro Alonso', 'Un hombre de cincuenta y cuatro años sale de una cárcel en la provincia de Corrientes. Lo único que quiere es llegar hasta donde está su hija, que vive en un lugar perdido rodeado de agua y selva. Para llegar hasta donde está su familia deberá atravesar un largo trayecto de agua en una canoa.', '/153bDV9xmiQADtFFGKgUubNeUro.jpg', '/bVvZaEGe0iQCSSLBkB1lX12ZS7F.jpg', 6.4, null, '{encuesta2022}'),
  (94649, 'movie', 'La libertad', 'La libertad', 'La libertad', 2001, 'Lisandro Alonso', 'Misael vive en la inmensidad del monte pampeano trabajando con su hacha. Sobrevive sólo con lo indispensable y casi sin contacto con otras personas. Vemos su vida minuto a minuto intentando descubrir a través de pequeños movimientos o acciones su manera de estar en el mundo. (FILMAFFINITY)', '/fBsf01Ah9Dzma73EXqFcGzV6fJJ.jpg', '/4SFSia8VdxyUi2WJq3GI4rE3olv.jpg', 6.3, null, '{encuesta2022}'),
  (426086, 'movie', 'Hombre de la esquina rosada', 'El hombre de la esquina rosada', 'El hombre de la esquina rosada', 1962, 'René Múgica', 'Un convicto recibe el beneficio del indulto durante los festejos por el Centenario de la Revolución de Mayo en Argentina.', '/snckGBOFomaRFSzpFWajsyCCxy3.jpg', '/7XwhAnLikeVz925vJM0saM0Edgj.jpg', 6.5, null, '{encuesta2022}'),
  (364940, 'movie', 'Habeas corpus', 'Habeas Corpus', 'Habeas Corpus', 1986, 'Jorge Acha', null, '/lH3sFOmL6zqE0ZiZXhWnCvkSJht.jpg', '/jLOxfF9ZezxoeZJYseqZ9yncwmr.jpg', 4.8, null, '{encuesta2022}'),
  (41115, 'movie', 'Garage Olimpo', 'Garage Olimpo', 'Garage Olimpo', 1999, 'Marco Bechis', 'Durante la Dictadura militar, María vive en Buenos Aires con su madre en una gran casa en decadencia. Han alquilado algunas habitaciones, y en una de ellas vive Félix, un joven tímido, enamorado de María, que, al parecer, trabaja de vigilante en un garaje. María enseña a leer ya escribir en un barrio pobre y, además, pertenece a una organización que lucha contra la dictadura militar. Una mañana, unos soldados de paisano la detienen y la llevan al Garage Olimpo, uno de los lugares donde se tortura a los activistas ante la indiferencia o ignorancia general. El encargado del centro elige a uno de sus mejores hombres para hacer el interrogatorio.', '/nFeWTpVShAfEIdvWwO9Sc9muZSG.jpg', '/eDgznD35ujsh35AiUcOybxJSSuU.jpg', 6.9, 'IOx-1euY05w', '{encuesta2022}'),
  (72776, 'movie', 'Aniceto', 'Aniceto', 'Aniceto', 2008, 'Leonardo Favio', 'Aniceto es un hombre solitario que vive con su gallo en un pueblito de Mendoza. Francisca es una chica ingenua que llega al lugar en busca de trabajo. Se conocen y se enamoran. Parece un sueño, pero termina en pesadilla cuando aparece la enigmática e irresistible Lucía, su nueva vecina, que perturba al hombre y lo arrastra a su propia destrucción.', '/9koqJ4smvVcYxPLWKsFOLWPEPoc.jpg', '/va28swtcuIovFDhArDywAkwizI3.jpg', 5.9, null, '{encuesta2022}'),
  (123763, 'movie', 'Yo, la peor de todas', 'Yo, la peor de todas', 'Yo, la peor de todas', 1990, 'María Luisa Bemberg', 'Obra inspirada en el ensayo "Las trampas de la fe", de Octavio Paz. Narra los últimos años de la célebre y bellísima Juana Inés de la Cruz (conocida en México como la Décima Musa), que a los veinte años ingresó en un convento para poder estudiar. La Corona española y la Iglesia, dos poderes a veces enfrentados, determinaron la vida de Sor Juana. En el México colonial, los virreyes la protegían, pero la Iglesia la censuraba por enseñar canto a sus alumnas y por dedicarse a la astronomía, la poesía, el teatro, la filosofía y la teología. Sor Juana pagaría muy caro su fervor poético y más aún su atrevimiento teológico. Al independizarse México, pierde la protección de la Corona y queda sola frente a su confesor, un miembro de la Inquisición, y al arzobispo de México, un misógino fanático. También el obispo de Puebla le tiende una trampa, en la que Sor Juana cae con la ingenuidad de los inocentes.', '/dmh9O5PvbDipFwsfBNKM4IUjkJT.jpg', '/kkfXj8hpO0GopXF7DLTmwEuVMlA.jpg', 6.0, null, '{encuesta2022}'),
  (427803, 'movie', 'Mujeres que trabajan', 'Mujeres que trabajan', 'Mujeres que trabajan', 1938, 'Manuel Romero', 'Ana María del Solar es una rica dama, que de repente queda en la calle. Luego de un tiempo va a vivir a la pensión en dónde vive su chofer.', '/bjQPVVan2Vfa9dBvDVPxLO7r0fF.jpg', '/grOwpvAn9YM6qW1m7JHTO2EzQiy.jpg', 8.2, null, '{encuesta2022}'),
  (199518, 'movie', 'Los isleros', 'Los isleros', 'Los isleros', 1951, 'Lucas Demare', 'Leandro y la Carancha son habitantes de las islas del Delta del Paraná y conforman una pareja. Son personas rudas, hechas a la dura lucha por la vida en esos parajes. Tienen un hijo que un día lleva a la casa a una muchacha; la presencia de ella provoca los celos de la Carancha y su actitud conduce a dramáticos conflictivos, rompiendo la armonía.', '/r6CxjfFPztcrSZzvW2yDf1mZtG8.jpg', '/myB2GXOZqTlYKyYJErqxJvSKqO3.jpg', 6.8, null, '{encuesta2022}'),
  (126104, 'movie', 'Los guantes mágicos', 'Los guantes mágicos', 'Los guantes mágicos', 2003, 'Martín Rejtman', 'Alejandro es un taxista de unos treinta y cinco años que se encuentra de pronto en medio de separaciones, cambios climáticos violentos, riqueza súbita, personajes que quieren volver a Argentina, otros que quieren irse para siempre, guantes mágicos, música ensordecedora, empobrecimiento repentino, incontables viajes al aeropuerto, una nueva relación, depresiones extremas, adicciones diversas... Nada de esto parece afectarle demasiado. En realidad, lo único que verdaderamente le importa es su Renault 12.', '/m6C10ZCm15wDTo7nXhbVGXpg51p.jpg', '/2iphMECIWgez9bybdNjEQPKlmWt.jpg', 6.4, null, '{encuesta2022}'),
  (656276, 'movie', 'Las mil y una', 'Las mil y una', 'Las mil y una', 2020, 'Clarisa Navas', 'Cuando Iris conoce a Renata, entre los monoblocks de Las Mil viviendas, siente una atracción inexplicable. La nueva presencia de Renata incomoda y los prejuicios se esparcen. Ante la hostilidad, ellas y su pequeño grupo de amigos serán la resistencia queer, haciendo que esas arquitecturas derruidas se vuelvan tan cómplices como riesgosas y que sus encuentros sean luz en la noche barrial.', '/eDEH0UskbrTEOXgDk6H1k0btWUz.jpg', '/jLGjIzysY2YvbHRT80x3WCPeFsr.jpg', 6.0, null, '{encuesta2022}'),
  (300427, 'movie', 'La guerra gaucha', 'La guerra gaucha', 'La guerra gaucha', 1942, 'Lucas Demare', 'En el año 1817, durante la Guerra de la Independencia, en la provincia de Salta, las fuerzas irregulares que respondían al general Martín Güemes hieren en una acción de guerrillas a un teniente del ejército español, peruano de nacimiento. El mismo es mantenido cautivo en la estancia de una patriota, de nombre Asunción, mientras le dan atención médica.', '/jwHNG295R6tySe5hxZidddTb2Y2.jpg', '/wv59sI29ZJWkUklkC7HoyswTyXY.jpg', 6.7, null, '{encuesta2022}'),
  (57981, 'movie', 'Rapado', 'Rapado', 'Rapado', 1992, 'Martín Rejtman', 'Rapado es la historia de jóvenes que rodean los veinte años en donde sus acciones están marcadas más por el azar que por la aventura. A Lucio le roban su motocicleta, su dinero y sus zapatillas. A partir de ese momento, se rapa por completo y empieza a obsesionarse con la idea de poder robar una moto similar a cualquier persona. Sus intentos por llevar a cabo el robo lo llevan a encuentros que se disparan en varias direcciones y se entrelazan de manera enrevesada e inesperada.', '/iUt4T9rSkNKPzywrYrDU4io12qt.jpg', '/73CVsYBF2bKLJeZz3PrfLdjtcYZ.jpg', 6.5, 'AdgbHoEdANw', '{encuesta2022}'),
  (243934, 'movie', 'Parapalos', 'Parapalos', 'Parapalos', 2004, 'Ana Poliak', 'Un chico de campo intenta encontrar su lugar en Buenos Aires. Se va a vivir con su prima a los suburbios y trabaja como parapalos en uno de los últimos bowling de la ciudad.', '/14zctn9wWWsJvBpYOM2dDIgYrzW.jpg', '/38k1u3kfp3rrziCvGI2xARyHYAF.jpg', 8.3, null, '{encuesta2022}'),
  (241603, 'movie', 'Miss Mary', 'Miss Mary', 'Miss Mary', 1986, 'María Luisa Bemberg', 'La acción se desarrolla en una inmensa estancia argentina y se inicia en el verano de 1938. Es la historia de una familia, símbolo de la oligarquía, que durante más de 50 años manejó el país como si fuera su propia estancia. Sus integrantes, alejados de la realidad que se aproxima, sordos a los rumores de un mundo que va cambiando sus estructuras, e indiferentes a todo lo que no sea ellos mismos y un poco a la manera de los personajes de Chejov, sueñan un sueño del que despertarán abruptamente con la llegada de Juan Domingo Perón en 1945. Todas estas circunstancias, transcurridas entre 1938 y 1945, son recordadas por una singular mujer, la institutriz inglesa Miss Mary (Julie Christie).', '/c17ysVjJhbii6XEE3n6rGalaEO8.jpg', '/qaGXAodqScdFT4bKD5Yj9ozyQjM.jpg', 6.7, null, '{encuesta2022}'),
  (456892, 'movie', 'Las furias', 'Las furias', 'Las furias', 1960, 'Vlasta Lah', 'Cinco mujeres (madre, esposa, amante, hermana e hija) intentan doblegar a un hombre hasta llevarlo a la muerte. Es el primer film sonoro dirigido por una mujer en Argentina.', '/pImMFiFzWZ1jDVex5AvwCGUEIYk.jpg', '/uDhCaVVnTfYBd2rg5HBZDR0N082.jpg', 7.5, null, '{encuesta2022}'),
  (269119, 'movie', 'Fin de fiesta', 'Fin de fiesta', 'Fin de fiesta', 1960, 'Leopoldo Torre Nilsson', 'Este drama rutinario ambientado en Argentina durante la década de 1930 establece paralelismos entre un patriarca familiar y un déspota político que recurre a cualquier medio corrupto para aumentar su poder y riqueza. Los paralelos son fáciles de hacer porque el hombre es el mismo en ambos casos. El abuelo de la familia tiene un control rígido y férreo sobre sus nietos, quienes eventualmente comienzan a rebelarse contra su comportamiento autoritario e irónicamente puritano. Al principio, no hay una conciencia real de su comportamiento criminal opuesto fuera del hogar. Pero a medida que uno de los nietos comienza a madurar en su conocimiento político, el abuelo finalmente es objeto de un merecido ataque.', '/5k23o0N78WVs0aIVEfMSxKSVEX.jpg', '/3PQ3yRWnnPiERaLocupAklwuHEd.jpg', 6.8, null, '{encuesta2022}'),
  (71118, 'movie', 'Felicidades', 'Felicidades', 'Felicidades', 2000, 'Lucho Bender', 'Es Nochebuena en Argentina. Un escritor famoso que no es feliz y que decide viajar al encuentro de su amada; un médico que quiere ligar con una española, y un odontólogo loco por encontrar el juguete que su hijo quiere de regalo. Una ácida visión sobre la otra cara de la navidad, donde la clase media insiste en sostener una celebración que ya ha perdido su naturaleza. Todos la festejan, pero se centra en los que quedan fuera: los protagonistas, que transitan en un mundo al revés, un mundo en el que irónicamente los justicieros se vuelven delincuentes y los nobles, miserables.', '/ozRxMgEMNITFS2tGRha3da7pJIW.jpg', null, 8.0, null, '{encuesta2022}'),
  (455966, 'movie', 'El camino hacia la muerte del viejo Reales', 'El camino hacia la muerte del viejo Reales', 'El camino hacia la muerte del viejo Reales', 1971, 'Gerardo Vallejo', 'La vida en los ingenios tucumanos a través del relato de un campesino tucumano y sus tres hijos.  El camino hacia la muerte del viejo Reales es una película documental de Argentina filmada en blanco y negro dirigida por Gerardo Vallejo según su propio guion escrito en colaboración con Pino Solanas y Octavio Getino que fue producida entre 1968 y 1971 y se estrenó el 10 de abril de 1974.  El filme está acompañado por dos anexos, uno con datos e imágenes de la provincia de Tucumán y otro con una crónica de la lucha de los campesinos del lugar.', '/ts8dbKa7hx7fjpGQrUmP5XU1r9a.jpg', '/4EXXjBXWYzTDFAQ5JGt6heTzGBm.jpg', 6.6, null, '{encuesta2022}'),
  (49681, 'movie', 'El abrazo partido', 'El abrazo partido', 'El abrazo partido', 2004, 'Daniel Burman', 'Narra la historia de un "adolescente tardío" que busca un pasaporte para huir de Argentina pero al que el regreso de su padre, que abandonó a la familia por un ideal, le trastoca los planes. Pese a ello, y gracias a este reencuentro, el hijo buscará a través de su padre su propia identidad.', '/mzSOWZegxvPdgwgiH4LG6b2mfxM.jpg', '/5JuJmZw4kmX3ncwblFEhB3VJvlq.jpg', 6.6, 'eDstswKJRTE', '{encuesta2022}'),
  (526465, 'movie', 'Vidalita', 'Vidalita', 'Vidalita', 1949, 'Luis Saslavsky', 'Vidalita es una joven sin familia cercana que pasa a ser acogida por un tío que vive en el campo. Sin embargo, su tío nunca la ha conocido y, además, cree que en vez de sobrina tiene un sobrino. Para poder cumplir con las expectativas de su tío y sobrevivir, decide hacerse pasar por un hombre.', '/1v4DAgZyzXhgXOgfavL4VOxMJRM.jpg', '/5E5hC9WdpHHKCG0RPAHp7m4vElG.jpg', 7.0, null, '{encuesta2022}'),
  (44989, 'movie', 'Los paranoicos', 'Los paranoicos', 'Los paranoicos', 2008, 'Gabriel Medina', '"Los paranoicos" cuenta la historia de Gauna, un joven que escribe pero nunca tuvo el coraje de enseñar su obra. Un hombre que en la intimidad expone una personalidad que parece censurar en su escasa vida social. La aparición de un viejo amigo, Manuel, que llega desde España embriagado por el suceso de una serie televisiva cuyo protagonista tiene un nombre que remite a él, provoca el enfrentamiento de Gauna con aquello que desea -aunque sea la novia de su amigo- y la reafirmación de sus principios.', '/p19IbmHnLn9PBotkryqs61p2IXU.jpg', '/4qdOErh4Lc5nemYVNKrT0hzhf8E.jpg', 6.8, 'OBEGof6rJlY', '{encuesta2022}'),
  (299152, 'movie', 'Las veredas de Saturno', 'Las veredas de Saturno', 'Les Trottoirs de Saturne', 1986, 'Hugo Santiago', 'Fabian Cortés, un músico latinoamericano, virtuoso del bandoneón, desaparece de su casa parisina donde vive desde hace doce años. Su mujer, Danielle, una joven abogada, decide avisar a la policía tras una investigación infructuosa. Unos días después, Fabián reaparece sin dar ninguna explicación.', '/g51FDmxyLI2MbT0EcWQRxrlwioH.jpg', '/ocIrQgcAxs1Xftdjvy8OGFWdMwc.jpg', 6.0, null, '{encuesta2022}'),
  (335366, 'movie', 'La vuelta al nido', 'La vuelta al nido', 'La vuelta al nido', 1938, 'Leopoldo Torres Ríos', 'Enrique, un oficinista gris que vive un matrimonio ya sin pasión, comienza a replantearse su vida cuando recibe un anónimo que dice que su mujer lo engaña.', '/1s4kHTrHlV6t0rKhykCpVZ2MUo3.jpg', '/jbwgAFWhaWpV89E5X6ALQeQ5ezM.jpg', 5.9, null, '{encuesta2022}'),
  (13317, 'movie', 'La antena', 'La antena', 'La antena', 2007, 'Esteban Sapir', 'En una ciudad futurista, los residentes han perdido sus voces ante el omnipotente Señor TV y la corporación sin nombre que manda la metrópoli.', '/hHe7E6zHtSnqa0iI7EO54jrHySE.jpg', '/xy7lAlRJh3aQCoqjdc5UpOQhaPt.jpg', 7.2, 'dMs0n0qUMUY', '{encuesta2022}'),
  (501916, 'movie', 'Dar la cara', 'Dar la cara', 'Dar la cara', 1962, 'José A. Martínez Suárez', 'Tres muchachos de orígenes muy distintos que acaban de terminar el servicio militar deben enfrentarse a la compleja realidad social argentina.', '/ePD6isiT90ERdbqU3fhyxiOkz7S.jpg', '/wyK4ttNdqg2wvWHqOkb4vgv22s1.jpg', 6.7, null, '{encuesta2022}'),
  (539685, 'movie', 'Rojo', 'Rojo', 'Rojo', 2018, 'Benjamín Naishtat', 'A mediados de los años 70, un hombre extraño llega a una tranquila ciudad de provincias. En un restaurante, y sin motivos aparentes, comienza a agredir a Claudio, un reconocido abogado. La comunidad apoya al abogado y el extraño es humillado y expulsado del lugar. Más tarde y camino a casa, Claudio y su mujer, Susana, son interceptados por el hombre extraño, quien está determinado a cobrarse una terrible venganza. El abogado toma entonces un camino sin retorno, de muerte, secretos y silencios.', '/nl2EEP3DsIyZLDklOgO6cNyx4Tl.jpg', '/cyvfdiZZ9nT7sXw8miSxpQEqyn6.jpg', 6.2, 'FLymVFShr1Q', '{encuesta2022}'),
  (242143, 'movie', 'P3ND3JO5', 'P3nd3jo5', 'P3nd3jo5', 2013, 'Raúl Perrone', 'P3ND3JO5 es musical, con fantasmas, con skaters. Una cumbiópera en tres actos y una coda para ver de corrido. De caras / miradas / deseo / amor / drama / tragedia / disparos / imagen cruda en ByN - 4:3.', '/4KtvJnqPgp3EYuuv9VG3Gbw1mth.jpg', '/vUdkI8HTrr9QNtyGD1mP282qEYB.jpg', 4.6, 'yr_exOVyeIs', '{encuesta2022}'),
  (335279, 'movie', 'La cabalgata del circo', 'La cabalgata del circo', 'La cabalgata del circo', 1945, 'Mario Soffici', 'La cabalgata del circo evoca la rica evolución, desarrollada entre 1880 y 1930, que comenzó en el circo criollo nómada de Argentina, el cual incluía representaciones teatrales breves ("pantomimas") en una misma función con payasos y otros números más convencionales de actuación circense.', '/yeDF1Sbla8GoDrmptXLcpaqIyI5.jpg', '/cShpz8IlBXDDiQbGE7LBbA0gAdY.jpg', 7.2, null, '{encuesta2022}'),
  (763180, 'movie', 'Esquirlas', 'Esquirlas', 'Esquirlas', 2020, 'Natalia Garayalde', 'El 3 noviembre de 1995 estalló la industria emblema de mi ciudad, la Fábrica Militar de Río Tercero, Córdoba. Miles de proyectiles se dispararon contra el pueblo que los producía, una tragedia que dejó siete muertos y centenares de heridos. Con 12 años, mientras intentaba escapar de las explosiones, registré la destrucción de mi ciudad con una cámara de video. Veinte años después, me encontré con esos archivos. La amenaza del polo industrial y militar aún persiste en el presente.', '/petrOvupCNkpSTOB4RODx95bgru.jpg', '/uB2KAUZldH0RWsVVIFE3ssCgRve.jpg', 7.5, null, '{encuesta2022}'),
  (298112, 'movie', 'El secuestrador', 'El secuestrador', 'El secuestrador', 1958, 'Leopoldo Torre Nilsson', 'Un grupo de personas pobres, que viven con lo mínimo indispensable en un barrio miserable, trata de sobrevivir en un mundo en el que parece no haber lugar para ellos. Con un tono crudo y realista la historia retrata sus tragedias cotidianas, sus amores, sus modos de subsistencia y su lucha diaria por sobrevivir.', '/9Lwz7QqXNYuCvNFVwEu75Vv2yoQ.jpg', '/fD5F11Sx5giThiWeYQbpzexeXy9.jpg', 5.7, null, '{encuesta2022}'),
  (124304, 'movie', 'De eso no se habla', 'De eso no se habla', 'De eso no se habla', 1993, 'María Luisa Bemberg', 'Leonor, una rica viuda, está muy orgullosa de su única hija, de trece años. Sólo hay un problema: la chica es enana. Leonor, toda una autoridad, ha logrado que la gente no hable del problema de su hija. Y, curiosamente, un soltero rico, por el que suspiraban las damas, se enamora de la muchacha.', '/sMdl025aldu01XzMsi0LUGjX0r4.jpg', '/atfoe8sASsuGruWp0qNRq1adKJE.jpg', 6.5, null, '{encuesta2022}'),
  (763673, 'movie', 'Adiós a la memoria', 'Adiós a la memoria', 'Adiós a la memoria', 2020, 'Nicolás Prividera', '“Me pasé toda la vida preguntándome sobre la función del recuerdo, que no eslo contrario del olvido, sino más bien su reverso. No recordamos, reescribimos la memoria como se reescribe la historia”, dijo Chris Marker, un director que, al igual que Nicolás Prividera, siempre consideró al cine como una herramienta contra el olvido, que nunca debe dejar delado la política y debe mostrar las consecuencias que ejerce sobre la sociedad. En Adiós a la memoria un padre registra la vida de su hijo en filmaciones caseras, imágenes que más tarde su hijo, ante la enfermedad irreversible de su progenitor, utiliza para realizar una película que da cuenta de la difícil relación entre ellos y la historia de un país que parece insistir en no aprender de sus errores.', '/ay3QCgGHdGukpChKqbPqsHnTZEj.jpg', '/oBlQM8CqBW9OC7SVXIGORZheQaD.jpg', 7.9, null, '{encuesta2022}')
on conflict (tmdb_id, media_type) where tmdb_id is not null do update
  set listas = array(select distinct unnest(peliculas.listas || excluded.listas));
